-- QA-only: add five domain-appropriate curriculum/reference choices to each of the five main forms.
UPDATE education.service_catalog
SET form_fields = form_fields || CASE service_code
WHEN 'early_childhood_registration' THEN '[{"key":"curriculum_reference","type":"select","label":"مرجع المنهج أو الإطار التعليمي","required":true,"options":[{"label":"المنهج السعودي لرياض الأطفال","value":"saudi_early_childhood"},{"label":"منهج مونتيسوري","value":"montessori"},{"label":"منهج ريجيو إميليا","value":"reggio_emilia"},{"label":"منهج هاي سكوب","value":"high_scope"},{"label":"التعلم القائم على اللعب والاستكشاف","value":"play_based_learning"},{"label":"مرجع آخر","value":"other"}]},{"key":"curriculum_reference_other","type":"text","label":"اسم المرجع الآخر (عند اختيار مرجع آخر)","required":false}]'::jsonb
WHEN 'general_education_registration' THEN '[{"key":"curriculum_reference","type":"select","label":"مرجع المنهج أو الإطار التعليمي","required":true,"options":[{"label":"المنهج السعودي","value":"saudi_curriculum"},{"label":"المنهج اليمني","value":"yemeni_curriculum"},{"label":"المنهج المصري","value":"egyptian_curriculum"},{"label":"المنهج الأردني","value":"jordanian_curriculum"},{"label":"إطار كامبردج / البكالوريا الدولية بحسب الإتاحة","value":"cambridge_ib_framework"},{"label":"مرجع آخر","value":"other"}]},{"key":"curriculum_reference_other","type":"text","label":"اسم المرجع الآخر (عند اختيار مرجع آخر)","required":false}]'::jsonb
WHEN 'university_guidance' THEN '[{"key":"curriculum_reference","type":"select","label":"مرجع الخطة الأكاديمية","required":true,"options":[{"label":"الخطة الدراسية المنشورة للجامعة أو الجهة","value":"institution_study_plan"},{"label":"الإطار الوطني للمؤهلات","value":"national_qualifications_framework"},{"label":"نظام الساعات الأوروبي ECTS","value":"ects_framework"},{"label":"إطار الساعات الأكاديمية البريطاني","value":"uk_credit_framework"},{"label":"نظام الساعات المعتمدة الأمريكي","value":"us_credit_hours"},{"label":"مرجع آخر","value":"other"}]},{"key":"curriculum_reference_other","type":"text","label":"اسم المرجع الآخر (عند اختيار مرجع آخر)","required":false}]'::jsonb
WHEN 'course_registration' THEN '[{"key":"curriculum_reference","type":"select","label":"مرجع المنهج أو المعيار التدريبي","required":true,"options":[{"label":"المعايير المهنية الوطنية","value":"national_occupational_standards"},{"label":"التدريب القائم على الكفايات TVET","value":"competency_based_tvet"},{"label":"إطار BTEC المهني","value":"btec_framework"},{"label":"معايير City & Guilds","value":"city_guilds_standards"},{"label":"معايير تقنية مهنية من الجهة المزودة","value":"vendor_technical_standards"},{"label":"مرجع آخر","value":"other"}]},{"key":"curriculum_reference_other","type":"text","label":"اسم المرجع الآخر (عند اختيار مرجع آخر)","required":false}]'::jsonb
WHEN 'activity_join' THEN '[{"key":"curriculum_reference","type":"select","label":"مرجع البرنامج أو الإطار","required":true,"options":[{"label":"إطار التعلم مدى الحياة","value":"lifelong_learning_framework"},{"label":"إطار المهارات الحياتية والاجتماعية","value":"life_social_skills_framework"},{"label":"إطار الريادة والقيادة","value":"entrepreneurship_leadership_framework"},{"label":"إطار التربية الفنية والإبداع","value":"arts_creativity_framework"},{"label":"إطار الأنشطة الرياضية والترفيهية","value":"sports_recreation_framework"},{"label":"مرجع آخر","value":"other"}]},{"key":"curriculum_reference_other","type":"text","label":"اسم المرجع الآخر (عند اختيار مرجع آخر)","required":false}]'::jsonb
ELSE '[]'::jsonb END,
updated_at=now()
WHERE service_code IN ('early_childhood_registration','general_education_registration','university_guidance','course_registration','activity_join')
AND NOT (form_fields @> '[{"key":"curriculum_reference"}]'::jsonb);
